/**
 * Options for configuring a serializable fetch request passed through the Dashboard.
 * @public
 */
export type SerializableRequestOptions = {
    /** The request body content. */
    body?: string | URLSearchParams;
    /** The cache mode for the request. */
    cache?: RequestCache;
    /** The credentials mode for the request. */
    credentials?: RequestCredentials;
    /** HTTP headers to include with the request. */
    headers?: object;
    /** A cryptographic hash of the resource to verify integrity. */
    integrity?: string;
    /** The HTTP method to use. */
    method?: 'GET' | 'POST' | 'PUT' | 'HEAD' | 'DELETE' | 'PATCH';
    /** The request mode (e.g. cors, no-cors, same-origin). */
    mode?: RequestMode;
    /** How to handle redirects. */
    redirect?: RequestRedirect;
    /** The referrer URL. */
    referrer?: string;
    /** The referrer policy. */
    referrerPolicy?: ReferrerPolicy;
    /** The request URL (used internally). */
    url?: string;
};
/**
 * A serializable representation of a fetch response returned through the Dashboard.
 * @public
 */
export type SerializableResponse = {
    /** The parsed JSON body, if available. */
    json?: Object;
    /** The raw response body as an ArrayBuffer, if available. */
    arrayBuffer?: ArrayBuffer;
    /** The response headers as a key-value map. */
    headers: {
        [key: string]: string;
    };
    /** Whether the response status is in the 200-299 range. */
    ok: boolean;
    /** Whether the response was the result of a redirect. */
    redirected: boolean;
    /** The HTTP status code. */
    status: number;
    /** The HTTP status text. */
    statusText: string;
    /** The response type (e.g. basic, cors). */
    type: string;
    /** The final URL after any redirects. */
    url: string;
};
